  str_n27_bh1_sub_name_2 = "EX1-2 Desespero",
  str_n27_bh2_sub_name_1 = "EX2-1 Thornflash",
  str_n27_bh2_sub_name_2 = "EX2-2 Predador",
  str_n27_bh3_sub_name_1 = "EX3-1 Crânio Tóxico",
